mapper.update:
UPDATE inventory_stock_position
SET quantity = quantity - #{delta},
    revision = revision + 1,
    updated_at = CURRENT_TIMESTAMP
WHERE household_id = #{householdId}
  AND lot_id = #{lotId}
  AND location_id = #{locationId}
  AND quantity - #{delta} >= 0

mapper.select:
SELECT sp.lot_id AS "lotId", sp.location_id AS "locationId", sp.quantity, sp.revision, sp.updated_at AS "updatedAt", i.name AS "itemName", i.management_type AS "itemManagementType", u.name AS "unitName", l.lot_number AS "lotNumber", l.serial_number AS "serialNumber", l.expiry_date AS "expiryDate" FROM inventory_stock_position sp JOIN inventory_lot l ON l.id = sp.lot_id JOIN catalog_item i ON i.id = l.item_id JOIN catalog_unit u ON u.id = i.unit_id
sp.household_id = #{householdId} AND l.item_id = #{itemId} AND sp.location_id = #{locationId}
ORDER BY ${orderBy}
